$(document).ready(function() {
    $('.btn-login-submit').on('click',function(e){
        e.preventDefault();
        var username = $('#loginForm').find('input[name="j_username"]').val();
        if (username == '') {
            $('#loginForm').find('input[name="j_username"]').focus();
            return;
        }
        var password = $('#loginForm').find('input[name="j_password"]').val();
        if (password == '') {
            $('#loginForm').find('input[name="j_password"]').focus();
            return;
        }
        var authRequest = {};
        authRequest.client_id = username;
        authRequest.client_secret = password;
        authRequest.grant_type = 'password';
        authRequest.scope = 'read';
        $.ajax({
            url: '/auto-create-member.json',
            type: 'POST',
            data: JSON.stringify(authRequest),
            dataType: "json",
            contentType: "application/json",
            success: function(result){
                if (result.errorMessage == null) {
                    $('#loginForm').submit();
                } else {
                    $('#auto-message').html(result.errorMessage);
                    $('#auto-message').removeClass('d-none');
                }
            },
            error: function (e){
                console.log('...................', e)
            }
        });
    })
});